:root {
    /* 字体设置 - 使用更现代的字体栈 */
    --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", "Helvetica Neue", Arial, sans-serif;
    --font-weight-normal: 400;
    --font-weight-medium: 500;
    --font-weight-bold: 600;
    --font-size-body: 14px;
    --font-size-label: 15px;
    --font-size-test-notice: 13px;
    --font-size-input: 15px;
    --font-size-header: 24px;
    --font-size-paragraph: 15px;
    --font-size-link: 13px;
    --font-size-error: 13px;
    --font-size-html-h1: 32px;
    --font-size-html-h2: 24px;
    --font-size-html-h3: 20px;
    --font-size-html-h4: 16px;
    --font-size-html-h5: 14px;
    --font-size-html-h6: 12px;
    --font-size-subheader: 16px;

    /* 现代化配色方案 */
    --color-background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    --color-test-notice-text: #f59e0b;
    --color-test-notice-bg: #fef3c7;
    --color-test-notice-border: #fcd34d;
    --color-card-bg: rgba(255, 255, 255, 0.95);
    --color-card-border: rgba(255, 255, 255, 0.2);
    --color-card-shadow: rgba(0, 0, 0, 0.1);
    --color-link: #6366f1;
    --color-header: #1f2937;
    --color-label: #374151;
    --color-input-border: #d1d5db;
    --color-input-text: #1f2937;
    --color-input-bg: #ffffff;
    --color-focus-border: #6366f1;
    --color-focus-shadow: rgba(99, 102, 241, 0.2);
    --color-submit-btn-bg: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    --color-submit-btn-text: #ffffff;
    --color-submit-btn-hover: linear-gradient(135deg, #5a67d8 0%, #6b46c1 100%);
    --color-error: #ef4444;
    --color-success: #10b981;
    --color-required: #ef4444;
    --color-clear-button-bg: #6b7280;
    --color-html-text: #374151;
    --color-html-link: #6366f1;
    --color-header-subtext: #6b7280;

    /* 现代化圆角 */
    --border-radius-card: 16px;
    --border-radius-input: 8px;
    --border-radius-button: 8px;
    --border-radius-clear-btn: 50%;
    --card-border-radius: 16px;

    /* 优化间距 */
    --padding-container-top: 32px;
    --padding-card: 32px;
    --padding-test-notice-vertical: 16px;
    --padding-test-notice-horizontal: 24px;
    --margin-bottom-card: 24px;
    --padding-form-input: 16px;
    --card-padding: 32px;
    --card-margin-bottom: 24px;

    /* 尺寸 */
    --container-width: 480px;
    --submit-btn-height: 52px;
    --checkbox-size: 20px;

    /* 现代化阴影和效果 */
    --box-shadow-card: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
    --box-shadow-input-focus: 0 0 0 3px var(--color-focus-shadow);
    --box-shadow-button: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --box-shadow-button-hover: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
    --opacity-placeholder: 0.6;
    --transition-all: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  }

  /* 容器样式 */
  .form-container {
    background: var(--color-background);
    min-height: 100vh;
    padding: var(--padding-container-top) 16px;
    font-family: var(--font-family);
    line-height: 1.6;
  }

  /* 卡片样式 */
  .form-card {
    background: var(--color-card-bg);
    border: 1px solid var(--color-card-border);
    border-radius: var(--border-radius-card);
    box-shadow: var(--box-shadow-card);
    padding: var(--padding-card);
    margin: 0 auto var(--margin-bottom-card);
    max-width: var(--container-width);
    backdrop-filter: blur(10px);
    transition: var(--transition-all);
  }

  .form-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.15);
  }

  /* 测试通知样式 */
  .test-notice {
    background: var(--color-test-notice-bg);
    border: 1px solid var(--color-test-notice-border);
    border-radius: var(--border-radius-input);
    color: var(--color-test-notice-text);
    font-size: var(--font-size-test-notice);
    font-weight: var(--font-weight-medium);
    padding: var(--padding-test-notice-vertical) var(--padding-test-notice-horizontal);
    margin-bottom: 24px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .test-notice::before {
    content: "⚠️";
    font-size: 16px;
  }

  /* 标题样式 */
  .form-header {
    color: var(--color-header);
    font-size: var(--font-size-header);
    font-weight: var(--font-weight-bold);
    margin-bottom: 8px;
    text-align: left; /* 将标题从居中改为左对齐 */
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .form-subheader {
    color: var(--color-header-subtext);
    font-size: var(--font-size-subheader);
    font-weight: var(--font-weight-normal);
    margin-bottom: 32px;
    text-align: left !important; /* 强制左对齐 */
    line-height: 1.5;
  }

  /* 表单组样式 */
  .form-group {
    margin-bottom: 24px;
  }

  /* 标签样式 */
  .form-label {
    color: var(--color-label);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    margin-bottom: 8px;
    display: block;
  }

  .form-label.required::after {
    content: " *";
    color: var(--color-required);
  }

  /* 输入框样式 */
  .form-input,
  .form-select,
  .form-textarea {
    background: var(--color-input-bg);
    border: 2px solid var(--color-input-border);
    border-radius: var(--border-radius-input);
    color: var(--color-input-text);
    font-family: var(--font-family);
    font-size: var(--font-size-input);
    padding: var(--padding-form-input);
    width: 100%;
    transition: var(--transition-all);
    box-sizing: border-box;
  }

  .form-input:focus,
  .form-select:focus,
  .form-textarea:focus {
    border-color: var(--color-focus-border);
    box-shadow: var(--box-shadow-input-focus);
    outline: none;
    transform: translateY(-1px);
  }

  .form-input::placeholder,
  .form-textarea::placeholder {
    color: var(--color-input-text);
    opacity: var(--opacity-placeholder);
  }

  /* 复选框样式 */
  .form-checkbox {
    appearance: none;
    width: var(--checkbox-size);
    height: var(--checkbox-size);
    border: 2px solid var(--color-input-border);
    border-radius: 4px;
    background: var(--color-input-bg);
    cursor: pointer;
    position: relative;
    transition: var(--transition-all);
  }

  .form-checkbox:checked {
    background: var(--color-focus-border);
    border-color: var(--color-focus-border);
  }

  .form-checkbox:checked::after {
    content: "✓";
    color: white;
    font-size: 14px;
    font-weight: bold;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
  }

  .form-checkbox:focus {
    box-shadow: var(--box-shadow-input-focus);
  }

  /* 按钮样式 - 强制覆盖 */
  .form-submit-btn,
  button.form-submit-btn,
  input[type="submit"].form-submit-btn,
  button[type="submit"] {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%) !important;
    background-image: linear-gradient(135deg, #667eea 0%, #764ba2 100%) !important;
    background-color: #667eea !important;
    border: none !important;
    border-radius: var(--border-radius-button) !important;
    color: #ffffff !important;
    cursor: pointer !important;
    font-family: var(--font-family) !important;
    font-size: var(--font-size-input) !important;
    font-weight: var(--font-weight-medium) !important;
    height: var(--submit-btn-height) !important;
    width: 100% !important;
    transition: var(--transition-all) !important;
    box-shadow: var(--box-shadow-button) !important;
    position: relative !important;
    overflow: hidden !important;
    text-shadow: none !important;
  }

  .form-submit-btn::before {
    content: "" !important;
    position: absolute !important;
    top: 0 !important;
    left: -100% !important;
    width: 100% !important;
    height: 100% !important;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent) !important;
    transition: left 0.5s !important;
  }

  .form-submit-btn:hover,
  button.form-submit-btn:hover,
  input[type="submit"].form-submit-btn:hover,
  button[type="submit"]:hover {
    background: linear-gradient(135deg, #5a67d8 0%, #6b46c1 100%) !important;
    background-image: linear-gradient(135deg, #5a67d8 0%, #6b46c1 100%) !important;
    background-color: #5a67d8 !important;
    box-shadow: var(--box-shadow-button-hover) !important;
    transform: translateY(-2px) !important;
  }

  .form-submit-btn:hover::before {
    left: 100% !important;
  }

  .form-submit-btn:active {
    transform: translateY(0) !important;
  }

  .form-submit-btn:disabled {
    opacity: 0.6 !important;
    cursor: not-allowed !important;
    transform: none !important;
  }

  /* 错误样式 */
  .form-error {
    color: var(--color-error);
    font-size: var(--font-size-error);
    margin-top: 8px;
    display: flex;
    align-items: center;
    gap: 6px;
  }

  .form-error::before {
    content: "⚠";
    font-size: 14px;
  }

  .form-input.error,
  .form-select.error,
  .form-textarea.error {
    border-color: var(--color-error);
    box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.1);
  }

  /* 成功样式 */
  .form-success {
    color: var(--color-success);
    font-size: var(--font-size-error);
    margin-top: 8px;
    display: flex;
    align-items: center;
    gap: 6px;
  }

  .form-success::before {
    content: "✓";
    font-size: 14px;
  }

  /* 链接样式 */
  .form-link {
    color: var(--color-link);
    font-size: var(--font-size-link);
    text-decoration: none;
    transition: var(--transition-all);
    font-weight: var(--font-weight-medium);
  }

  .form-link:hover {
    text-decoration: underline;
    color: var(--color-focus-border);
  }

  /* 清除按钮样式 */
  .form-clear-btn {
    background: var(--color-clear-button-bg);
    border: none;
    border-radius: var(--border-radius-clear-btn);
    color: white;
    cursor: pointer;
    font-size: 12px;
    height: 24px;
    width: 24px;
    transition: var(--transition-all);
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .form-clear-btn:hover {
    background: var(--color-error);
    transform: scale(1.1);
  }

  /* HTML内容样式 */
  .form-html-content {
    color: var(--color-html-text);
    font-size: var(--font-size-paragraph);
    line-height: 1.6;
  }

  .form-html-content h1 {
    font-size: var(--font-size-html-h1);
    font-weight: var(--font-weight-bold);
    margin-bottom: 16px;
  }
  .form-html-content h2 {
    font-size: var(--font-size-html-h2);
    font-weight: var(--font-weight-bold);
    margin-bottom: 14px;
  }
  .form-html-content h3 {
    font-size: var(--font-size-html-h3);
    font-weight: var(--font-weight-bold);
    margin-bottom: 12px;
  }
  .form-html-content h4 {
    font-size: var(--font-size-html-h4);
    font-weight: var(--font-weight-bold);
    margin-bottom: 10px;
  }
  .form-html-content h5 {
    font-size: var(--font-size-html-h5);
    font-weight: var(--font-weight-bold);
    margin-bottom: 8px;
  }
  .form-html-content h6 {
    font-size: var(--font-size-html-h6);
    font-weight: var(--font-weight-bold);
    margin-bottom: 6px;
  }

  .form-html-content a {
    color: var(--color-html-link);
    text-decoration: none;
    font-weight: var(--font-weight-medium);
    transition: var(--transition-all);
  }

  .form-html-content a:hover {
    text-decoration: underline;
    color: var(--color-focus-border);
  }

  /* 响应式设计 */
  @media (max-width: 640px) {
    .form-container {
      padding: 16px 12px;
    }

    .form-card {
      padding: 24px;
      border-radius: 12px;
    }

    .form-header {
      font-size: 20px;
    }

    .form-subheader {
      font-size: 14px;
    }
  }

  /* 加载动画 */
  @keyframes pulse {
    0%,
    100% {
      opacity: 1;
    }
    50% {
      opacity: 0.5;
    }
  }

  .form-loading {
    animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  }

  .form-textarea {
    min-height: 120px !important; /* 从原来的80px增加到120px (1.5倍) */
    resize: vertical; /* 允许用户垂直调整大小 */
    font-family: var(--font-family);
    line-height: 1.5;
  }

  /* 添加notes元素样式，使用占位符颜色 */
  .notes,
  .notes,
  [class*="notes"],
  *[data-notes],
  .form-notes {
    color: var(--color-input-text);
    opacity: var(--opacity-placeholder) !important; /* 使用占位符透明度 */
    font-size: var(--font-size-input);
    font-family: var(--font-family);
    font-style: italic;
    margin-top: 4px !important; /* 缩短与上方元素的距离 */
    margin-bottom: 12px;
    line-height: 1.4;
  }

  /* 特别针对Element Name为notes的元素 */
  notes {
    display: block;
    color: var(--color-input-text);
    opacity: var(--opacity-placeholder) !important;
    font-size: var(--font-size-input);
    font-family: var(--font-family);
    font-style: italic;
    margin-top: 4px !important; /* 缩短距离 */
    margin-bottom: 12px;
    line-height: 1.4;
  }

