    'Malay': 'ms'
};

// 从输入数据中提取种子关键词和意图字段
const inputData = $input.first().json;
const seedKeywords = [];

// 提取intent_sentence和intent_word字段
const intentSentence = inputData.intent_sentence || null;
const intentWord = inputData.intent_word || null;

// 提取并转换location和language字段
const locationName = inputData.location || 'Global';
const languageName = inputData.language || 'No Limit';
const locationCode = locationMap[locationName];
const languageCode = languageMap[languageName];

console.log('提取的意图字段:');
console.log(`  intent_sentence: ${intentSentence}`);
console.log(`  intent_word: ${intentWord}`);
console.log('提取的位置和语言字段:');
console.log(`  location: ${locationName} → location_code: ${locationCode}`);
console.log(`  language: ${languageName} → language_code: ${languageCode}`);

// 提取所有keyword开头的字段
Object.keys(inputData).forEach(key => {
    if (key.startsWith('keyword') && inputData[key]) {
        seedKeywords.push(inputData[key]);
    }
});

console.log(`\n发现 ${seedKeywords.length} 个种子关键词: ${seedKeywords.join(', ')}`);

// 为每个种子关键词创建独立的输出项
const output = seedKeywords.map(keyword => ({
    json: {
        seed_keyword: keyword,
        timestamp: new Date().toISOString()
    }
}));

// 在最后添加意图字段作为单独的字典项
output.push({
    json: {
        intent_sentence: intentSentence,
        intent_word: intentWord
    }
});

// 添加位置和语言代码字典
output.push({
    json: {
        location_code: locationCode,
        language_code: languageCode
    }
});

console.log(`\n输出 ${seedKeywords.length} 个关键词 + 1 个意图字段字典 + 1 个位置语言配置字典`);

return output;

