// 计算单词数的辅助函数
function countWords(keyword) {
  if (!keyword) return 0;
  // 按空格分割并过滤空字符串
  return keyword.trim().split(/\s+/).filter(word => word.length > 0).length;
}

// 处理单个关键词数据
function processKeyword(keywordData, index) {
  // 处理location_code
  let locationValue = keywordData.location_code;
  if (locationValue === null || locationValue === undefined) {
    locationValue = "global";
  } else if (locationMap[String(locationValue)]) {
    locationValue = locationMap[String(locationValue)];
  }

  // 计算单词数
  const wordCount = countWords(keywordData.keyword);

  // 保存last_updated_time的值
  const lastUpdatedTime = keywordData.last_updated_time || null;

  // 构建新的数据结构（按指定顺序）
  const processedKeyword = {
    // 在seed_keyword前添加
    "number": null,  // 序号先设为null，后续根据需要排序后再赋值
    "priority": null,

    // 原有字段
    "seed_keyword": keywordData.seed_keyword || null,

    // 在keyword前添加
    "main_category": null,
    "sub_category": null,

    // keyword字段
    "keyword": keywordData.keyword || null,

    // 在keyword后添加
    "intent_type": null,
    "word_count": wordCount,

    // 原有字段（删除api_type，处理location_code）
    "location_code": locationValue,
