// 关键词转文本节点 - 将JSON格式的关键词数据转换为文本格式供大模型使用
// 输入：keyword_processor的输出（包含keywords数组）
// 输出：适合Google Gemini等大模型处理的文本格式

// 配置选项
const CONFIG = {
  // 输出模式：single（单个合并文本）, batch（批量单独处理）, prompt（带上下文的prompt）
  outputMode: 'batch',  // 默认批量模式

  // 批处理大小（仅在batch模式下有效）
  batchSize: 500,

  // 文本分隔符（所有模式都使用英文逗号）
  separator: ', ',

  // 是否包含额外信息
  includeMetadata: false,

  // prompt模板（仅在prompt模式下有效）
  promptTemplate: '请分析以下关键词：{keywords}'
};

// 处理单个关键词，提取需要的信息
function processKeywordForText(keyword) {
  const parts = [];

  // 基础信息：关键词本身
  parts.push(keyword.keyword);

  // 如果需要包含元数据
  if (CONFIG.includeMetadata) {
    const metadata = [];
    if (keyword.search_volume) {
      metadata.push(`搜索量:${keyword.search_volume}`);
    }
    if (keyword.competition_level) {
      metadata.push(`竞争度:${keyword.competition_level}`);
    }
    if (keyword.word_count) {
      metadata.push(`单词数:${keyword.word_count}`);
    }

    if (metadata.length > 0) {
      parts.push(`(${metadata.join(', ')})`);
    }
  }

  return parts.join(' ');
}

// 生成单个合并文本
function generateSingleText(keywords) {
  const textList = keywords.map(kw => processKeywordForText(kw));
  return textList.join(CONFIG.separator);
}

// 生成批量处理的多个item
function generateBatchItems(keywords) {
  const items = [];

  // 按批次大小分组
  for (let i = 0; i < keywords.length; i += CONFIG.batchSize) {
    const batch = keywords.slice(i, i + CONFIG.batchSize);
    // 使用逗号分隔,最后一个关键词后也加逗号
    const batchText = batch.map(kw => processKeywordForText(kw)).join(', ') + ', ';

    const textWithNewline = batchText;
    const messageWithNewline = batchText;

    items.push({
      json: {
        text: textWithNewline,
        message: messageWithNewline,  // 兼容不同的大模型节点
        keywords: batch.map(kw => kw.keyword),  // 保留原始关键词列表
        batch_index: Math.floor(i / CONFIG.batchSize) + 1,
        batch_size: batch.length,
        metadata: {
          total_keywords: keywords.length,
          current_batch: Math.floor(i / CONFIG.batchSize) + 1,
          total_batches: Math.ceil(keywords.length / CONFIG.batchSize)
        }
      }
    });
  }

  return items;
}

// 生成带prompt的格式
function generatePromptFormat(keywords) {
  const keywordText = generateSingleText(keywords);
  const prompt = CONFIG.promptTemplate.replace('{keywords}', keywordText);

  return {
    json: {
      text: prompt,
      message: prompt,
      prompt: prompt,
      keywords: keywords.map(kw => kw.keyword),
      metadata: {
        total_keywords: keywords.length,
        mode: 'prompt'
      }
    }
  };
}

