// N8N节点：将AI分析结果映射到关键词数据中
// 功能：通过keyword匹配，将intent_type和final_score填入对应的intent_type和keyword_intent_score
// 输入：上一个节点的JSON数据（包含AI分析结果数组 + metadata和keywords对象）
// 输出：只包含metadata和keywords的JSON对象

try {
    const inputItems = $input.all();

    if (!inputItems || inputItems.length === 0) {
        throw new Error('未接收到输入数据');
    }

    // N8N节点输出的数据可能有多种格式
    // 1. 直接是数组：inputItems本身就是多个item
    // 2. 单个item包含数组：inputItems[0].json是数组
    let rawData = null;

    // 尝试从第一个item获取数据
    if (inputItems[0].json) {
        rawData = inputItems[0].json;
        // 处理可能的多层包装
        if (rawData.data) {
            rawData = rawData.data;
        }
    }

    // 如果不是数组，尝试将所有items合并
    if (!Array.isArray(rawData)) {
        rawData = inputItems.map(item => item.json);
    }

    if (!Array.isArray(rawData)) {
        throw new Error('输入数据格式错误：无法解析为数组格式');
    }

    console.log(`接收到 ${rawData.length} 个数据项`);

    // 3.json的格式：
    // [
    //   {AI分析结果1: keyword, intent_type, final_score...},
    //   {AI分析结果2: ...},
    //   ...
    //   {最后一个元素: metadata: {...}, keywords: [...]}
    // ]

    // 数组最后一个元素应该是包含metadata和keywords的对象
    const lastItem = rawData[rawData.length - 1];

    if (!lastItem || !lastItem.metadata || !lastItem.keywords) {
        throw new Error('数据格式错误：数组最后一个元素应包含metadata和keywords字段');
    }

    const keywordData = lastItem;
    // 除最后一个元素外，其他都是AI分析结果
    const analysisResults = rawData.slice(0, -1);

    if (!keywordData || !keywordData.keywords) {
        throw new Error('未找到包含keywords字段的数据');
    }

    console.log(`找到 ${analysisResults.length} 条AI分析结果`);
    console.log(`找到 ${keywordData.keywords.length} 个关键词待处理`);

    // 创建keyword到分析结果的映射表
    const analysisMap = new Map();
    for (const analysis of analysisResults) {
        analysisMap.set(analysis.keyword, analysis);
    }

    // 统计信息
    let matchedCount = 0;
    let unmatchedKeywords = [];
    let unmatchedAnalysis = new Set(analysisMap.keys());

    // 遍历keywords数组，填充intent_type和keyword_intent_score
    for (const keyword of keywordData.keywords) {
        const keywordText = keyword.keyword;

        if (analysisMap.has(keywordText)) {
            const analysis = analysisMap.get(keywordText);

            // 填充字段
            keyword.intent_type = analysis.intent_type;
            keyword.keyword_intent_score = analysis.final_score;

            matchedCount++;
            unmatchedAnalysis.delete(keywordText);
        } else {
            unmatchedKeywords.push(keywordText);
        }
    }

    // 输出统计信息
