// N8N节点：关键词SEO数据评分系统
// 功能：根据keyword_scoring.md规则对关键词进行评分
// 输入：上一个节点的JSON数据（包含metadata和keywords）
// 输出：包含所有评分字段的JSON对象

// 1. 搜索量评分（满分30分）
function calculateSearchVolumeScore(searchVolume) {
    if (searchVolume > 50000) return 30;
    if (searchVolume >= 10001) return 25;
    if (searchVolume >= 5001) return 20;
    if (searchVolume >= 1001) return 15;
    if (searchVolume >= 101) return 10;
    return 5;
}

// 2.1 CPC评分（满分10分）
function calculateCpcScore(cpc) {
    if (cpc === null || cpc <= 0.25) return 10;
    if (cpc <= 0.75) return 8;
    if (cpc <= 1.50) return 6;
    if (cpc <= 3.00) return 4;
    return 2;
}

// 2.2 竞争指数评分（满分10分）
function calculateCompetitionScore(competition) {
    if (competition === null || competition <= 0.20) return 10;
    if (competition <= 0.40) return 8;
    if (competition <= 0.60) return 6;
    if (competition <= 0.80) return 4;
    return 2;
}

// 2.3 页面顶部出价评分（满分10分）
function calculateBidScore(lowBid, highBid) {
    if (lowBid === null && highBid === null) return 10;

    let avgBid;
    if (lowBid === null) {
        avgBid = highBid;
    } else if (highBid === null) {
        avgBid = lowBid;
    } else {
        avgBid = (lowBid + highBid) / 2;
    }

    if (avgBid <= 0.50) return 10;
    if (avgBid <= 1.50) return 8;
    if (avgBid <= 3.00) return 6;
    if (avgBid <= 5.00) return 4;
    return 2;
}

// 3. 意向类别评分（满分20分）
function calculateIntentTypeScore(intentType) {
    const scoreMap = {
        'Direct Intent': 20,
        'Indirect Intent': 12,
        'Less Relevant': 4,
        'Irrelevant': 0
    };
    return scoreMap[intentType] || 0;
}

// 4. 优先级分级（ABC三级）
function calculatePriority(totalScore) {
    if (totalScore >= 83) return 'A';
    if (totalScore >= 65) return 'B';
    return 'C';
}

try {
    const inputItems = $input.all();

    if (!inputItems || inputItems.length === 0) {
        throw new Error('未接收到输入数据');
    }

    // 获取输入数据
    let rawData = inputItems[0].json;

    // 处理可能的多层包装
    if (rawData.data) {
        rawData = rawData.data;
    }

    // 如果是数组，取第一个元素
    const data = Array.isArray(rawData) ? rawData[0] : rawData;

    if (!data.keywords || !Array.isArray(data.keywords)) {
        throw new Error('数据格式错误：未找到keywords数组');
    }

    console.log(`\n找到 ${data.keywords.length} 个关键词待评分\n`);

    let processedCount = 0;
    const priorityStats = { A: 0, B: 0, C: 0 };

    // 遍历每个关键词进行评分
    for (const keyword of data.keywords) {
        // 1. 搜索量评分
        keyword.search_volume_score = calculateSearchVolumeScore(keyword.search_volume || 0);

        // 2. 竞争度评分
        keyword.base_competition_score = calculateCompetitionScore(keyword.competition);
        keyword.cpc_score = calculateCpcScore(keyword.cpc);
        keyword.bid_score = calculateBidScore(keyword.low_top_of_page_bid, keyword.high_top_of_page_bid);

        // 计算总竞争度评分
        keyword.total_competition_score =
            keyword.base_competition_score +
            keyword.cpc_score +
            keyword.bid_score;

        // 3. 意向类别评分
        keyword.intent_type_score = calculateIntentTypeScore(keyword.intent_type);

        // 4. 计算总分
        keyword.total_score =
            keyword.search_volume_score +
            (keyword.keyword_intent_score || 0) +
            keyword.intent_type_score +
            keyword.total_competition_score;

        // 5. 分配优先级
        keyword.priority = calculatePriority(keyword.total_score);
        priorityStats[keyword.priority]++;

        processedCount++;

        // 显示前3个处理示例
        if (processedCount <= 3) {
            console.log(`示例 ${processedCount}: ${keyword.keyword}`);
            console.log(`  搜索量评分: ${keyword.search_volume_score}`);
            console.log(`  关键词意图评分: ${keyword.keyword_intent_score}`);
