            console.log(`  竞争度评分: ${keyword.total_competition_score} (基础:${keyword.base_competition_score} + CPC:${keyword.cpc_score} + 出价:${keyword.bid_score})`);
            console.log(`  总分: ${keyword.total_score}`);
            console.log(`  优先级: ${keyword.priority}\n`);
        }
    }

    // 输出统计信息
    console.log('=== 评分完成统计 ===');
    console.log(`总处理关键词: ${processedCount} 个`);
    console.log(`A级关键词: ${priorityStats.A} 个 (84-100分)`);
    console.log(`B级关键词: ${priorityStats.B} 个 (65-83分)`);
    console.log(`C级关键词: ${priorityStats.C} 个 (<65分)`);

    // 更新metadata
    data.metadata.processing_stage = 'scored';
    data.metadata.scored_at = new Date().toISOString();
    data.metadata.priority_distribution = priorityStats;

    // 返回结果给下一个节点
