} catch (error) {
    console.error('❌ 评分失败:', error.message);
    console.error('错误堆栈:', error.stack);
    throw error;
}

// N8N节点：准备数据用于CSV转换
// 功能：从{metadata, keywords}格式提取keywords数组，以便Convert to File节点正确转换为CSV
// 输入：上一个节点的JSON数据（包含metadata和keywords）
// 输出：keywords数组（每个关键词作为独立的item）

try {
    const inputItems = $input.all();

    if (!inputItems || inputItems.length === 0) {
        throw new Error('未接收到输入数据');
    }

    // 获取输入数据
    let rawData = inputItems[0].json;

    // 处理可能的多层包装
    if (rawData.data) {
        rawData = rawData.data;
    }

    // 如果是数组，取第一个元素
    const data = Array.isArray(rawData) ? rawData[0] : rawData;

    if (!data.keywords || !Array.isArray(data.keywords)) {
        throw new Error('数据格式错误：未找到keywords数组');
    }

    console.log(`找到 ${data.keywords.length} 个关键词`);
    console.log('准备转换为CSV格式...\n');

    // N8N的Convert to File节点需要接收数组格式
    // 每个数组元素都是一个独立的item，会变成CSV的一行
    // 删除不需要的字段：number, main_category, sub_category
    const keywords = data.keywords.map(kw => {
        const cleaned = { ...kw };
        delete cleaned.number;
        delete cleaned.main_category;
        delete cleaned.sub_category;
        return cleaned;
    });

    console.log('前3个关键词预览:');
    keywords.slice(0, 3).forEach((kw, i) => {
        console.log(`${i + 1}. ${kw.keyword} - 优先级: ${kw.priority}, 总分: ${kw.total_score}`);
    });

    console.log('\n✅ 数据准备完成，可以传递给Convert to File节点');

    // 返回数组，每个元素会成为CSV的一行
    return keywords;

} catch (error) {
    console.error('❌ 数据准备失败:', error.message);
    console.error('错误堆栈:', error.stack);
    throw error;
}

// 关键词合并节点 V2 - 确保合并所有输入项
// 运行模式: Run Once for All Items
// 说明：这个版本会等待并合并所有输入项以及只保留1000个关键词

// 获取所有输入项
const allInputItems = $input.all();
console.log(`总共接收到 ${allInputItems.length} 个输入项`);

let allKeywords = [];
const processedAPIs = new Set();

// 处理所有输入项
allInputItems.forEach((inputItem, index) => {
    console.log(`处理输入项 ${index + 1}...`);

    // 检查是否是原始API响应
    const responseData = inputItem.json;

    // 处理已经是keywords格式的数据（来自之前的处理）
    if (responseData.keywords && Array.isArray(responseData.keywords)) {
        console.log(`输入项 ${index + 1} 已经是处理后的格式，包含 ${responseData.keywords.length} 个关键词`);
        allKeywords = allKeywords.concat(responseData.keywords);
        return;
    }

    // 处理原始API响应数据
    if (responseData && responseData.tasks && responseData.tasks[0]) {
        const path = responseData.tasks[0].path || [];
        let apiType = null;

        if (path.includes('keyword_suggestions')) {
            apiType = 'keyword_suggestions';
        } else if (path.includes('related_keywords')) {
            apiType = 'related_keywords';
        }

        if (apiType) {
            processedAPIs.add(apiType);
            console.log(`处理 ${apiType} API数据...`);

            const task = responseData.tasks[0];
            const taskData = task.data || {};
            const seedKeyword = taskData.keyword || null;
            const locationCode = taskData.location_code || null;
            const languageCode = taskData.language_code || 'en';

            if (task.result && task.result[0] && task.result[0].items) {
                const items = task.result[0].items;

                items.forEach(item => {
                    let keyword = null;
                    let keywordInfo = {};

                    if (apiType === 'keyword_suggestions') {
                        keyword = item.keyword;
                        keywordInfo = item.keyword_info || {};
                    } else if (apiType === 'related_keywords') {
                        if (item.keyword_data) {
                            keyword = item.keyword_data.keyword;
                            keywordInfo = item.keyword_data.keyword_info || {};
                        } else {
                            keyword = item.keyword;
                            keywordInfo = item.keyword_info || {};
                        }
                    }

                    if (keyword) {
                        allKeywords.push({
                            api_type: apiType,
                            seed_keyword: seedKeyword,
                            keyword: keyword,
                            location_code: locationCode,
                            language_code: languageCode,
                            search_volume: keywordInfo.search_volume || null,
                            cpc: keywordInfo.cpc || null,
                            competition: keywordInfo.competition || null,
                            competition_level: keywordInfo.competition_level || null,
                            last_updated_time: keywordInfo.last_updated_time || null,
                            low_top_of_page_bid: keywordInfo.low_top_of_page_bid || null,
                            high_top_of_page_bid: keywordInfo.high_top_of_page_bid || null
                        });
                    }
                });

                console.log(`从 ${apiType} 提取了 ${items.length} 个关键词`);
            }
        }
    }
});

console.log(`\n去重前统计：`);
console.log(`- 总关键词数：${allKeywords.length}`);
console.log(`- 处理的API类型：${Array.from(processedAPIs).join(', ')}`);

// 统计各API类型的关键词数量
const stats = {};
allKeywords.forEach(kw => {
    stats[kw.api_type] = (stats[kw.api_type] || 0) + 1;
});

Object.entries(stats).forEach(([type, count]) => {
    console.log(`- ${type}: ${count} 个关键词`);
});

// 基于keyword值进行去重和合并
console.log(`\n开始关键词去重合并...`);
const keywordMap = new Map();

allKeywords.forEach(kw => {
    const keyword = kw.keyword;

    if (keywordMap.has(keyword)) {
        // 如果关键词已存在，合并数据（取最大值）
        const existing = keywordMap.get(keyword);

        // 对数值字段取最大值
        existing.search_volume = Math.max(
            existing.search_volume || 0,
            kw.search_volume || 0
        ) || null;

        existing.cpc = Math.max(
            existing.cpc || 0,
            kw.cpc || 0
        ) || null;

        existing.competition = Math.max(
            existing.competition || 0,
            kw.competition || 0
        ) || null;

        existing.low_top_of_page_bid = Math.max(
            existing.low_top_of_page_bid || 0,
            kw.low_top_of_page_bid || 0
        ) || null;

        existing.high_top_of_page_bid = Math.max(
            existing.high_top_of_page_bid || 0,
            kw.high_top_of_page_bid || 0
        ) || null;

        // 更新时间取最新的
        if (kw.last_updated_time &&
            (!existing.last_updated_time || kw.last_updated_time > existing.last_updated_time)) {
            existing.last_updated_time = kw.last_updated_time;
        }

        // 如果现有竞争等级为null，使用新的
        if (!existing.competition_level && kw.competition_level) {
            existing.competition_level = kw.competition_level;
        }

    } else {
        // 新关键词，创建去重后的条目
        keywordMap.set(keyword, {
            api_type: "merge_deduplication",  // 固定值表示合并去重
            seed_keyword: kw.seed_keyword,
            keyword: keyword,
            location_code: null,  // 固定为null
            language_code: kw.language_code,
            search_volume: kw.search_volume || null,
            cpc: kw.cpc || null,
            competition: kw.competition || null,
            competition_level: kw.competition_level || null,
            last_updated_time: kw.last_updated_time || null,
            low_top_of_page_bid: kw.low_top_of_page_bid || null,
            high_top_of_page_bid: kw.high_top_of_page_bid || null
        });
    }
});

// 将Map转换为数组
const deduplicatedKeywords = Array.from(keywordMap.values());

console.log(`\n去重后统计：`);
console.log(`- 去重前关键词数：${allKeywords.length}`);
console.log(`- 去重后关键词数：${deduplicatedKeywords.length}`);
console.log(`- 移除重复关键词：${allKeywords.length - deduplicatedKeywords.length} 个`);

// 限制关键词数量为最多1000个
const MAX_KEYWORDS = 1000;
let finalKeywords = deduplicatedKeywords;
let limitApplied = false;
let discardedCount = 0;

if (deduplicatedKeywords.length > MAX_KEYWORDS) {
    finalKeywords = deduplicatedKeywords.slice(0, MAX_KEYWORDS);
    discardedCount = deduplicatedKeywords.length - MAX_KEYWORDS;
    limitApplied = true;

    console.log(`\n⚠️ 关键词数量限制：`);
    console.log(`- 去重后关键词数：${deduplicatedKeywords.length}`);
    console.log(`- 限制数量：${MAX_KEYWORDS}`);
    console.log(`- 保留关键词：${finalKeywords.length}`);
    console.log(`- 丢弃关键词：${discardedCount} 个`);
} else {
    console.log(`\n✅ 关键词数量在限制范围内（${deduplicatedKeywords.length} <= ${MAX_KEYWORDS}），无需限制`);
}

// 创建最终输出
const outputData = {
    metadata: {
        generated_at: new Date().toISOString(),
        total_keywords: finalKeywords.length,
        original_count: allKeywords.length,
        duplicates_removed: allKeywords.length - deduplicatedKeywords.length,
        limit_applied: limitApplied,
        max_keywords_limit: MAX_KEYWORDS,
        discarded_keywords: discardedCount
    },
    keywords: finalKeywords
};

// 返回单个数组项（重要：确保返回数组格式）
return [{
    json: outputData
}];

// N8N节点：将搜索量查询结果填充回原始关键词数据

try {
    console.log('开始合并搜索量数据...');

    const allInputs = $input.all();
    console.log(`接收到 ${allInputs.length} 个输入项`);

    let originalData = null;
    let searchVolumeResults = null;

    // 从两个输入项中提取数据
    allInputs.forEach((item, index) => {
        console.log(`处理输入项 ${index}...`);

        // 第一个输入项：原始关键词数据
        if (item.json && item.json.keywords && Array.isArray(item.json.keywords)) {
            originalData = item.json;
            console.log(`✓ 找到原始关键词数据，包含 ${originalData.keywords.length} 个关键词`);
        }

        // 第二个输入项：搜索量查询结果
        if (item.json && item.json.tasks && Array.isArray(item.json.tasks) &&
            item.json.tasks[0] && item.json.tasks[0].result && Array.isArray(item.json.tasks[0].result)) {
            searchVolumeResults = item.json.tasks[0].result;
            console.log(`✓ 找到搜索量结果，包含 ${searchVolumeResults.length} 个关键词`);
        }
    });

    if (!originalData || !searchVolumeResults) {
        throw new Error('未能找到完整的原始数据或搜索量结果');
    }

    // 创建搜索量映射表 - 关键词 -> 最新搜索量
    const volumeMap = new Map();

    searchVolumeResults.forEach(result => {
        const keyword = result.keyword;
        let latestVolume = result.search_volume; // 默认使用总搜索量

        // 如果有月度数据，使用最新月份的搜索量
        if (result.monthly_searches && Array.isArray(result.monthly_searches) && result.monthly_searches.length > 0) {
            latestVolume = result.monthly_searches[0].search_volume;
        }

        volumeMap.set(keyword, latestVolume);
    });

    console.log(`✓ 构建了 ${volumeMap.size} 个关键词的搜索量映射`);

    // 更新原始数据中的搜索量
    let updatedCount = 0;
    let skippedCount = 0;

    originalData.keywords.forEach(keywordItem => {
        const keyword = keywordItem.keyword;

        if (volumeMap.has(keyword)) {
            const newVolume = volumeMap.get(keyword);
            const oldVolume = keywordItem.search_volume;

            keywordItem.search_volume = newVolume;
            updatedCount++;

            if (newVolume !== oldVolume) {
                console.log(`✓ 更新 "${keyword}": ${oldVolume} -> ${newVolume}`);
            }
        } else {
            skippedCount++;
            console.log(`⚠ 跳过 "${keyword}": 未找到搜索量数据`);
        }
    });

    console.log(`\n=== 更新统计 ===`);
    console.log(`成功更新: ${updatedCount} 个关键词`);
    console.log(`跳过处理: ${skippedCount} 个关键词`);

    // 更新元数据时间戳
    originalData.metadata.last_updated_at = new Date().toISOString();
    originalData.metadata.search_volume_updated = true;

    console.log('✓ 数据更新完成，已删除搜索量结果部分');

    // 只返回更新后的原始关键词数据
    return originalData;

} catch (error) {
    console.error('处理过程中发生错误:', error.message);
    return {
        error: error.message,
        keywords: []
    };
}

// N8N节点：提取关键词并转换为DataForSEO搜索量查询API格式

// 主处理逻辑
try {
    console.log('开始处理关键词数据...');

    // 获取上一个节点的所有输入数据
    const inputItems = $input.all();
    console.log(`接收到 ${inputItems.length} 个输入项`);

    let keywords = [];

    // 处理输入项 - 只处理1.json格式
    inputItems.forEach((inputItem, index) => {
        const data = inputItem.json;

        // 1.json格式：包含keywords数组的对象
        if (data && data.keywords && Array.isArray(data.keywords)) {
            data.keywords.forEach(item => {
                if (item.keyword) {
                    keywords.push(item.keyword);
                }
            });
            console.log(`✓ 从keywords数组提取到 ${data.keywords.length} 个关键词`);
        }
    });

    if (keywords.length === 0) {
        throw new Error('未能提取到任何关键词');
    }

    // 输出统计信息
    console.log('\n=== 处理统计 ===');
    console.log(`提取到的唯一关键词数：${keywords.length}`);
    console.log('前10个关键词示例：', keywords.slice(0, 10));

    // 检查是否超过API限制
    if (keywords.length > 700) {
        console.log(`⚠️ 警告：关键词数量(${keywords.length})超过API单批限制(700)，建议分批处理`);
    }

    // 构建DataForSEO API请求体
    const apiRequestBody = [
        {
            keywords: keywords,
            search_partners: false
        }
    ];

    // 直接返回API请求体
    return apiRequestBody;

} catch (error) {
    console.error('处理过程中发生错误:', error.message);
    // 错误时返回空的API请求体
    return [
        {
            keywords: [],
            search_partners: false
        }
    ];
}

// 聚合节点 - 将多个items合并为单个item供Gemini批量处理
// 功能：替代executeOnce参数，符合mule-run标准
// 位置：应放置在 Merge_intent 和 Gemini_flash_2.5 之间
// 运行模式：Run Once for All Items

// 获取所有输入items
const allItems = $input.all();

console.log(`聚合节点：收到 ${allItems.length} 个输入items`);

// 分类提取数据
const keywordTexts = [];
let intentData = null;

allItems.forEach((item, index) => {
    const data = item.json;

    // 提取关键词文本
    if (data.text) {
        keywordTexts.push(data.text);
        console.log(`  [${index}] 关键词文本: ${data.text.substring(0, 50)}...`);
    }

    // 提取意图数据
    if (data.intent_sentence || data.intent_word) {
        intentData = {
            intent_sentence: data.intent_sentence || '',
            intent_word: data.intent_word || ''
        };
        console.log(`  [${index}] 意图数据: sentence="${intentData.intent_sentence}", word="${intentData.intent_word}"`);
    }
});

// 构建聚合后的单个item
const aggregatedItem = {
    json: {
        // 所有关键词文本（用于在Gemini prompt中展示）
        keyword_texts: keywordTexts,

        // 合并后的关键词文本字符串（方便直接在prompt中使用）
        keywords_combined: keywordTexts.join('\n\n'),

        // 意图数据
        intent_sentence: intentData ? intentData.intent_sentence : '',
        intent_word: intentData ? intentData.intent_word : '',

        // 元数据
        total_keywords: keywordTexts.length,
        aggregated_at: new Date().toISOString(),

        // 原始数据（如果需要完整访问）
        original_items: allItems.map(item => item.json)
    }
};

console.log(`\n聚合完成：${keywordTexts.length} 个关键词合并为 1 个item`);
console.log(`意图句子: "${aggregatedItem.json.intent_sentence}"`);
console.log(`意图词语: "${aggregatedItem.json.intent_word}"`);

// 返回单个聚合item
return [aggregatedItem];
